import React, { Component } from 'react'
import Form from 'react-bootstrap/Form'
import Button from 'react-bootstrap/Button'

class SearchForm extends Component {
    
    initialState = {
        url: ''
    }

    state = this.initialState
  
    handleChange = event => {
        const { name, value } = event.target
  
        this.setState({
          [name]: value,
        })
    }
    
    submitForm = () => {
        this.props.handleSubmit(this.state)
        //this.setState(this.initialState)
    }
    
    render() {
        const { url } = this.state;

        const showSubmitButton = props.showSubmitButton ? {display: 'block'} : {display: 'none'};
        const showSubmitLoadingButton = props.showSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
        
        return (
          <Form onSubmit={this.onFormSubmit} >
            <Form.Group>
                <Form.Label>Soundcloud Song URL</Form.Label>
                <Form.Control
                    type="url"
                    name="url"
                    id="url"
                    value={url}
                    onChange={this.handleChange} />
            </Form.Group>
    
            <Button type="submit" value="Submit" onClick={e => {e.preventDefault(); this.submitForm()}} style={showSubmitButton}>Submit</Button>
              <Button variant="primary" disabled style={showSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                Loading...
              </Button>
          </Form>
          
        );
    }

}

export default SearchForm;
